# -*- coding: utf-8 -*-
# Giro AJ (2026-10-28): genera NORMATIVA_UE_INTERNAZIONALE_PACK (12 schede, L2-L3,
# FACOLTA_GESTIONE_SISTEMA) — il sistema normativo europeo e internazionale come soggetto:
# CPR, marcatura CE, DoP, ETA/EAD, norme armonizzate, Eurocodici+NA, direttive UE,
# IBC/ASCE/NFPA, lettura delle sigle, verifica dei certificati, norma in contratto/cantiere.
# NON ridondante: CPR/CE/Eurocodici sono citati nei pack tecnici come riferimenti,
# mai trattati come sistema (verifica grep 28/10/2026).
import json, io, os

BASE = r'UNIVERSITA_EDILIZIA/NORMATIVA_UE_INTERNAZIONALE_PACK'
os.makedirs(os.path.join(BASE, 'schede'), exist_ok=True)

KEYS = ['categoria','nome','descrizione','tecnologia','applicazioni','vantaggi','limiti',
        'costi_e_economia','casi_real_world','normative','note_cantiere']

S = []
def add(**kw):
    assert list(kw.keys()) == KEYS, list(kw.keys())
    assert kw['costi_e_economia'].startswith('Ordini di grandezza indicativi: '), kw['nome']
    S.append(kw)

add(
 categoria="Fondamenti",
 nome="La gerarchia delle fonti tecniche: legge, decreto, norma volontaria, guida",
 descrizione="In edilizia convivono fonti di forza diversa: leggi e decreti (vincolanti), regolamenti UE (direttamente applicabili), norme tecniche UNI/EN/ISO (volontarie, ma...), circolari e guide. Sapere chi comanda cosa e' la prima competenza professionale: la maggior parte dei contenziosi tecnici nasce da una norma volontaria trattata come legge o da una legge trattata come consiglio.",
 tecnologia="Gerarchia: (1) Regolamenti UE: direttamente applicabili e prevalenti (es. Reg. UE 305/2011 sui prodotti da costruzione); (2) Direttive UE: vincolano il risultato, richiedono recepimento nazionale (es. EPBD, RED); (3) leggi e decreti nazionali: DPR 380/2001 (edilizia), D.Lgs 81/2008 (sicurezza), NTC D.M. 17/1/2018 (costruzioni), D.Lgs 152/2006 (ambiente); (4) norme tecniche (UNI, UNI EN, UNI EN ISO): VOLONTARIE per principio — diventano cogenti solo se richiamate da una legge/decreto (es. le norme richiamate dai decreti), dal contratto (capitolato) o come regola dell'arte in giudizio; (5) presunzione di conformita': le norme armonizzate citate in GU UE danno presunzione di conformita' ai requisiti essenziali dei regolamenti; (6) circolari ministeriali: spiegano, non innovano (la circolare non puo' derogare la legge); (7) guide e manuali di settore: buona pratica, non fonte; la data conta: edizione della norma, stato di ritiro/sostituzione, decorrenze di coesistenza.",
 applicazioni="Redazione di capitolati e contratti (richiamare la norma giusta con l'edizione giusta); difesa tecnica in contenzioso; valutazione di conformita' di prodotti e lavorazioni; interpretazione dei requisiti di legge vs requisiti contrattuali.",
 vantaggi="Chi conosce la gerarchia evita due errori opposti: sovradimensionare (imporre per 'legge' cio' che e' volontario: costi e contestazioni) e sottodimensionare (trattare come consiglio cio' che il decreto richiama: responsabilita'); in contenzioso, la citazione corretta della fonte decide spesso la perizia.",
 limiti="Il richiamo delle norme nei decreti italiani e' talvolta indiretto ('secondo la regola dell'arte', 'secondo le norme tecniche vigenti'): richiede interpretazione; le circolari ministeriali abbondano e talvolta eccedono; il sistema si muove (revisioni, ritiri, sostituzioni): serve aggiornamento continuo.",
 costi_e_economia="Ordini di grandezza indicativi: una norma UNI singola costa 40-120 € (abbonamenti professionali per banche dati normative: 300-1.500 €/anno); una consulenza legale-tecnica su conformita' normativa di prodotto o contratto: 1-5 k€; l'errore di citazione in un capitolato pubblico puo' costare l'annullamento della gara o la lite: decine di k€.",
 casi_real_world="Caso tipo: capitolato che richiedeva una specifica edizione di una norma UNI ritirata e sostituita: l'impresa ha eseguito secondo l'edizione vigente; la controversia si e' risolta riconoscendo che il richiamo contrattuale a norma ritirata va interpretato come richiamo alla norma sostitutiva, salvo diversa volonta' documentata.",
 normative="Reg. UE 305/2011 (CPR, direttamente applicabile); DPR 380/2001; D.Lgs 81/2008; D.M. 17/1/2018 (NTC); D.Lgs 152/2006; i principi sulla volontarieta' delle norme tecniche e sulla regola dell'arte sono consolidati nella giurisprudenza e nella pratica (regolamento UE 1025/2012 sulla standardizzazione europea per il quadro generale).",
 note_cantiere="Quando il capitolato dice 'secondo norma UNI XXXX', chiedi subito: quale edizione? Se e' ritirata, mettilo per iscritto nella conferenza pre-posa: eseguire 'a norma ritirata' o 'a norma vigente' senza chiarimento e' il modo piu' sicuro di pagare due volte lo stesso lavoro."
)

add(
 categoria="CPR",
 nome="Il Regolamento (UE) 305/2011 (CPR): il mercato unico dei prodotti da costruzione",
 descrizione="Il Construction Products Regulation e' la legge europea dei materiali da costruzione: stabilisce come un prodotto dimostra le sue prestazioni e circola nel mercato unico. Non e' un marchio di qualita': e' un sistema di dichiarazione delle prestazioni su requisiti comuni. Chi compra, specifica o posa prodotti da costruzione lavora dentro il CPR ogni giorno, spesso senza saperlo.",
 tecnologia="Struttura: sette requisiti di base delle OPERE (1 resistenza meccanica e stabilita'; 2 sicurezza in caso di incendio; 3 igiene, salute e ambiente; 4 sicurezza e accessibilita' nell'uso; 5 protezione dal rumore; 6 risparmio energetico e isolamento termico; 7 uso sostenibile delle risorse naturali); il CPR regola i PRODOTTI in funzione dei requisiti delle opere; strumenti: norme armonizzate (hEN) e Documenti di Valutazione Europei (EAD); il fabbricante dichiara le prestazioni con la Dichiarazione di Prestazione (DoP) e appone la marcatura CE; sistemi di valutazione e verifica della costanza della prestazione (AVCP) da 1+ (audit di terza parte con certificato di costanza) a 4 (solo dichiarazione del fabbricante): il sistema e' scritto nella norma armonizzata di prodotto, non e' una scelta; organismi notificati (laboratori e enti di certificazione) elencati nella banca dati NANDO della Commissione; il CPR e' regolamento: vale uguale in tutta l'UE, senza recepimento; in fase avanzata la revisione del regolamento (nuovo CPR adottato a fine 2024, applicazione progressiva: verificare numero, decorrenze e disciplina transitoria sul testo ufficiale EUR-Lex).",
 applicazioni="Qualunque prodotto da costruzione coperto da norma armonizzata o ETA: strutturale (cemento, acciaio, legno strutturale, laterizi), involucro (membrane, serramenti, vetri, isolanti), impianti (porte tagliafuoco, canaline), finiture; obblighi per fabbricanti, importatori, distributori; doveri di progettisti e direttori lavori nella specifica e nell'accettazione.",
 vantaggi="Linguaggio comune UE: la stessa prestazione dichiarata con lo stesso metodo di prova in tutti i paesi; la DoP rende confrontabili i prodotti su dati dichiarati e responsabilizzati; la libera circolazione abbatte le barriere tecniche nazionali; il progettista puo' specificare per prestazioni invece che per marche.",
 limiti="La marcatura CE NON e' un marchio di qualita' ne' di sicurezza assoluta: dichiara prestazioni su caratteristiche essenziali, spesso con valori 'NPD' (nessuna prestazione dichiarata) proprio sulle caratteristiche che servono; la sorveglianza del mercato e' nazionale e disomogenea; i prodotti non coperti da norma armonizzata possono marcare CE solo via ETA (volontaria): il resto e' fuori dal sistema; abusi di marcatura esistono: serve verifica documentale.",
 costi_e_economia="Ordini di grandezza indicativi: per il fabbricante, il percorso di marcatura CE su norma armonizzata con AVCP alto (prove iniziali di tipo, controllo produzione, audit) costa 10-60 k€ a famiglia di prodotto piu' i costi annuali di sorveglianza; per il cantiere, la verifica documentale delle DoP costa ore del direttore lavori, ma l'accettazione di un prodotto senza DoP o con DoP falsa puo' trasformarsi in demolizione, sostituzione e lite: ordini di grandezza di decine di k€ anche su commesse piccole.",
 casi_real_world="Caso tipo: fornitura di membrane con marcatura CE dichiarata: la verifica a campione del DL scopre che la DoP citava una norma armonizzata non pertinente al prodotto (norma di un'altra famiglia): fornitura bloccata, sostituzione a carico del fornitore, cantiere ripartito con prodotto conforme e DoP coerente.",
 normative="Reg. UE 305/2011 (CPR); Reg. UE 1025/2012 (standardizzazione europea); D.Lgs 106/2017 (adeguamento della normativa nazionale al CPR e disciplina sanzionatoria); nuovo Regolamento CPR adottato a fine 2024 con applicazione progressiva (verificare testo e decorrenze su EUR-Lex); banca dati NANDO della Commissione per gli organismi notificati.",
 note_cantiere="Alla consegna di un prodotto coperto da norma armonizzata esigi la DoP e leggi TRE cose: la norma citata (e' quella giusta per QUEL prodotto?), le caratteristiche dichiarate (c'e' il valore che ti serve o c'e' scritto NPD?), il numero dell'organismo notificato se il sistema AVCP lo prevede. Tre minuti che ti mettono al riparo."
)

add(
 categoria="CPR",
 nome="Marcatura CE e Dichiarazione di Prestazione (DoP): cosa deve contenere, cosa NON certifica",
 descrizione="La marcatura CE su un prodotto da costruzione e' la punta visibile di un fascicolo: la DoP. Il marchio dice 'il fabbricante dichiara'; la DoP dice 'cosa' e 'quanto'. Leggere una DoP e' una competenza di cantiere quotidiana: e' li' che si scopre se il prodotto e' adatto al TUO uso, non solo 'a norma'.",
 tecnologia="Contenuto obbligatorio della DoP (schema del CPR): identificazione del prodotto-tipo, usi previsti dal fabbricante, fabbricante e riferimenti, sistema AVCP, norma armonizzata o EAD/ETA di riferimento, prestazioni dichiarate per le caratteristiche essenziali (valori, classi o livelli) con metodi di prova, documentazione tecnica di supporto; la marcatura CE sul prodotto/imballo/documenti riporta: marchio CE, identificazione, norma di riferimento, e per i sistemi AVCP con terza parte il numero dell'organismo notificato (4 cifre); il NPD ('nessuna prestazione dichiarata') e' lecito: significa che il fabbricante NON dichiara quella caratteristica — per il progettista equivale a un dato mancante da gestire (altro documento, altra scelta, o esclusione); la DoP va conservata nel fascicolo dell'opera; le prestazioni dichiarate sono responsabilita' del fabbricante: la sorveglianza (D.Lgs 106/2017) punisce le dichiarazioni mendaci; attenzione alle 'CE cinesi' graficamente simili e alle marcature CE su prodotti fuori dal campo CPR: il marchio fuori contesto non vale nulla.",
 applicazioni="Accettazione dei materiali in cantiere; redazione di capitolati prestazionali (richiamare le caratteristiche essenziali e le classi, non le marche); verifica di coerenza tra DoP e requisiti di progetto (es. classe di resistenza, reazione al fuoco); controlli di sorveglianza e contenziosi.",
 vantaggi="Confronto oggettivo tra prodotti su dati omogenei; responsabilita' chiara del fabbricante; tracciabilita' documentale dell'opera (fascicolo); il sistema AVCP alto (1+, 1) aggiunge audit terzi reali sulla produzione.",
 limiti="La DoP copre solo le caratteristiche essenziali della norma di prodotto: durabilita', posa, compatibilita' di sistema restano spesso fuori; l'NPD abbonda proprio dove serve il dato; la DoP non dice nulla sull'idoneita' al TUO dettaglio (un prodotto conforme usato fuori dagli usi previsti e' un prodotto sbagliato); falsi documentali esistono: il numero dell'organismo si verifica su NANDO in due minuti.",
 costi_e_economia="Ordini di grandezza indicativi: la verifica documentale di un pacchetto di DoP di commessa costa 2-8 ore di DL (poche centinaia di euro); il prodotto 'equivalente' senza DoP verificabile puo' costare la sostituzione completa piu' la lite; la conservazione del fascicolo DoP: un archivio digitale ordinato, costo marginale nullo, valore enorme in garanzia.",
 casi_real_world="Caso tipo: pavimentazione industriale con requisito di classe di resistenza all'abrasione: la DoP del prodotto proposto riportava NPD sulla caratteristica; il DL ha richiesto e ottenuto il rapporto di prova del laboratorio come documentazione tecnica di supporto prima dell'accettazione, evitando l'accettazione 'sulla fiducia'.",
 normative="Reg. UE 305/2011 (allegati su DoP e marcatura CE; sistemi AVCP); D.Lgs 106/2017 (sorveglianza e sanzioni); le singole norme armonizzate di prodotto (citate in GU UE) per caratteristiche essenziali e sistemi di verifica; banca dati NANDO per la verifica degli organismi notificati.",
 note_cantiere="Crea la cartella 'DoP' nel fascicolo dal primo giorno e mettici OGNI consegna rilevante, con data e lotto: quando tra tre anni si scolla una guaina o freme una pavimentazione, quella cartella decide se hai un problema tuo o del fabbricante. E il numero dell'organismo notificato controllalo su NANDO: se non esiste, il marchio e' carta da parati."
)

add(
 categoria="CPR",
 nome="La via ETA: EAD, EOTA e la valutazione tecnica europea dei prodotti innovativi",
 descrizione="Non tutti i prodotti hanno una norma armonizzata: i sistemi innovativi (kit compositi, ancoranti speciali, sistemi a spruzzo) ottengono la marcatura CE attraverso la Valutazione Tecnica Europea (ETA), rilasciata dagli enti TAB della rete EOTA sulla base di Documenti di Valutazione Europei (EAD). Per il progettista, l'ETA e' il documento che trasforma un 'kit proprietario' in un prodotto specificabile.",
 tecnologia="Percorso: il fabbricante chiede l'ETA a un TAB (Technical Assessment Body) designato; il riferimento e' l'EAD applicabile (se esiste) o uno sviluppato per il caso; l'ETA contiene: descrizione del prodotto e usi previsti, prestazioni valutate per le caratteristiche essenziali, condizioni di installazione e posa (parte vincolante!), durata di vita utile presunta, documenti di supporto; con l'ETA il fabbricante emette la DoP e marca CE; l'EAD puo' derivare da vecchi ETAG (linee guida della direttiva precedente) convertiti; per il professionista: l'ETA e' il documento da richiedere e leggere INTEGRALMENTE per sistemi come impermeabilizzazioni liquide, ancoranti, connessioni strutturali, kit compositi: la scheda commerciale non basta mai; i riferimenti EAD citano il campo d'impiego: usare il prodotto fuori dal campo dell'ETA invalida la copertura; le ETA sono pubbliche presso i TAB e spesso sul sito del fabbricante: verificare versione e validita'.",
 applicazioni="Sistemi di impermeabilizzazione liquida (EAD ex ETAG 005); ancoranti post-installati per calcestruzzo; sistemi compositi di rinforzo; kit di fissaggio per facciate; prodotti innovativi senza norma armonizzata; capitolati che devono specificare sistemi proprietari per prestazioni.",
 vantaggi="Unica via europea per la marcatura CE dei prodotti senza norma armonizzata; l'ETA contiene prestazioni E condizioni d'uso valutate da terzi: molto piu' ricca di una scheda commerciale; consente al progettista di specificare per prestazioni sistemi innovativi; documento verificabile e versionato.",
 limiti="L'ETA e' volontaria: molti prodotti innovativi non ce l'hanno (e non possono marcare CE per quel campo); le condizioni di posa vincolanti sono spesso ignorate in cantiere (spessori, temperature, preparazione supporto): la conformita' del prodotto non copre la posa non conforme; i tempi e i costi dell'iter ETA per i fabbricanti sono rilevanti; la lettura richiede competenza: un ETA di 40 pagine non si riassume in una riga di capitolato.",
 costi_e_economia="Ordini di grandezza indicativi: iter ETA per un fabbricante (prove, valutazione TAB, emissione) 20-60 k€ a prodotto/kit, con tempi di 1-2 anni; per il progettista la verifica dell'ETA costa ore di studio; l'installazione di un kit fuori dalle condizioni dell'ETA puo' azzerare garanzia e copertura assicurativa: il danno si misura sul rifacimento.",
 casi_real_world="Caso tipo: impermeabilizzazione liquida di una copertura con molte emergenze: il capitolato richiedeva kit con ETA su EAD (ex ETAG 005); in posa la DL ha verificato che gli spessori umidi e la temperatura del supporto rispettassero le condizioni dell'ETA, registrando i valori a verbale: garanzia decennale attivata senza rilievi.",
 normative="Reg. UE 305/2011 (quadro ETA/EAD, ruolo di EOTA e dei TAB); gli EAD pertinenti per famiglia (es. EAD 030350-00-0402 per i kit liquidi di impermeabilizzazione, ex ETAG 005); rete EOTA e banche dati dei TAB per la verifica dei documenti; D.Lgs 106/2017 per la sorveglianza nazionale.",
 note_cantiere="Quando il capitolato cita un ETA, scaricalo e leggi le 'condizioni di installazione': spessori, umidita' del supporto, temperature, attrezzature. Poi le metti nel piano di posa e nel verbale. Il kit con ETA posato fuori condizioni e' un kit non coperto: te lo diranno al primo dissesto, e avranno ragione loro."
)

add(
 categoria="Norme",
 nome="Le norme armonizzate e la presunzione di conformita': la Gazzetta UE che conta",
 descrizione="Una norma diventa 'armonizzata' quando la Commissione la cita nella Gazzetta Ufficiale dell'Unione: da quel momento i prodotti conformi godono della presunzione di conformita' ai requisiti del CPR. L'elenco delle norme citate (e di quelle ritirate) e' pubblico: sapere dove guardarlo distingue il professionista aggiornato da quello che cita edizioni morte.",
 tecnologia="Meccanismo: norma elaborata dal CEN su mandato della Commissione -> citazione in GUUE (OJEU) -> presunzione di conformita' e possibilita' di marcatura CE per i prodotti coperti; fasi di coesistenza: per un periodo convivono vecchia e nuova edizione (la data di cessazione della presunzione della vecchia e' nella citazione); ritiro della citazione: la norma resta valida come norma tecnica ma non da' piu' presunzione per la marcatura; restrizioni: talvolta la citazione e' 'con avvertenza' (parti della norma non coperte); strumenti pratici: elenchi ufficiali delle norme armonizzate pubblicati dalla Commissione (EUR-Lex), siti degli enti di normazione (UNI, CEN) per lo stato delle edizioni (pubblicata, in inchiesta, ritirata, sostituita da); la sigla racconta lo stato: EN (norma europea), prEN (progetto), UNI EN (adozione italiana identica), UNI EN ISO (norma ISO adottata a livello europeo e nazionale); per il lavoro quotidiano: il richiamo in capitolato deve indicare norma ED edizione vigente alla data dell'appalto, o prevedere espressamente la sostitutiva.",
 applicazioni="Verifica della base normativa delle DoP; aggiornamento dei capitolati; gestione delle varianti quando una norma citata viene ritirata a lavori in corso; audit di conformita' dei fornitori; contenziosi su edizioni applicabili.",
 vantaggi="La presunzione di conformita' semplifica la dimostrazione di conformita' regolamentare; gli elenchi pubblici rendono verificabile tutto da ufficio; la coesistenza codificata evita vuoti giuridici alle transizioni.",
 limiti="Le citazioni cambiano: chi lavora su elenchi stampati lavora su dati morti (solo consultazione online aggiornata); le avvertenze di citazione sono ignorate dai piu' (e sono vincolanti); la giungla delle edizioni nazionali di adozione aggiunge un livello (una EN puo' avere edizioni nazionali con prefacce diverse); nessun servizio ti avvisa da solo: il monitoraggio e' un'attivita' da pianificare.",
 costi_e_economia="Ordini di grandezza indicativi: consultazione EUR-Lex e elenchi Commissione: gratuita; abbonamenti a servizi di normazione con alert sulle edizioni: 300-1.500 €/anno; il riferimento a norma ritirata in gara pubblica puo' generare ricorso e annullamento: costi legali di ordine 5-30 k€ e mesi di ritardo.",
 casi_real_world="Caso tipo: gara con richiamo a una norma di prodotto la cui citazione era stata ritirata e sostituita da nuova edizione con avvertenza: in sede di esecuzione, la DL ha richiesto ai fornitori DoP riferite all'edizione citata in GUUE alla data dell'appalto, chiudendo la questione con nota motivata prima delle consegne.",
 normative="Reg. UE 305/2011 e Reg. UE 1025/2012 (quadro della standardizzazione e citazioni); le citazioni ufficiali nella Gazzetta Ufficiale dell'Unione Europea (EUR-Lex); prassi CEN/UNI sullo stato delle norme (prefazioni e fascicoli delle singole norme).",
 note_cantiere="Metti nei preferiti la pagina EUR-Lex delle norme armonizzate CPR e quella UNI dello stato edizioni: prima di firmare un capitolato o accettare una DoP, due controlli online di cinque minuti. E quando una norma muore a meta' commessa, scrivi un verbale che fissa edizione applicabile e date: il silenzio si paga dopo."
)

add(
 categoria="Eurocodici",
 nome="Il sistema degli Eurocodici (EN 1990-1999): struttura, NDP e Annessi Nazionali",
 descrizione="Gli Eurocodici sono la famiglia europea delle norme di progettazione strutturale: dieci volumi, una grammatica comune (stati limite, coefficienti parziali), e un meccanismo di adattamento nazionale (i Parametri Determinati a livello Nazionale, NDP, negli Annessi Nazionali). Sono norme di calcolo, non leggi: in Italia lavorano in concerto con le NTC, che ne richiamano parti e ne sostituiscono altre.",
 tecnologia="Architettura: EN 1990 (basilari: stati limite, affidabilita', combinazioni), EN 1991 (azioni: pesi propri, carichi, neve, vento, termiche, incendio, urti), EN 1992 (cls armato), EN 1993 (acciaio), EN 1994 (miste acciaio-cls), EN 1995 (legno), EN 1996 (muratura), EN 1997 (geotecnica), EN 1998 (sismica), EN 1999 (alluminio); ogni volume e' articolato in parti; il sistema degli stati limite con coefficienti parziali su azioni e resistenze e' la spina dorsale; NDP: molti coefficienti sono 'a scatola aperta' con valore raccomandato europeo e scelta nazionale obbligata: l'Annesso Nazionale italiano (NTA) fissa i valori per l'Italia — un calcolo 'eurocodice' senza Annesso Nazionale non e' completo; in Italia: le NTC (D.M. 17/1/2018) sono la legge tecnica delle costruzioni e convivono con gli Eurocodici secondo il principio del doppio binario (le NTC fissano il quadro, gli Eurocodici con NA sono strumento di progetto riconosciuto; le parti non trattate dalle NTC trovano negli Eurocodici riferimento consolidato); seconda generazione degli Eurocodici: revisione in corso con pubblicazioni progressive (verificare lo stato di pubblicazione e le eventuali adozioni nazionali al momento del progetto).",
 applicazioni="Progettazione strutturale di opere nuove e valutazione delle esistenti; gare internazionali (gli Eurocodici sono la lingua comune); redazione di capitolati strutturali; verifica di progetti esteri per il mercato italiano e viceversa; cooperazione con progettisti di altri paesi UE.",
 vantaggi="Sistema coerente unico per tutti i materiali e le azioni; la struttura a stati limite e' la stessa ovunque: chi la padroneggia lavora in tutta Europa; gli NA permettono taratura nazionale senza rompere il quadro comune; la seconda generazione aggiorna il sistema a cinquant'anni di pratica.",
 limiti="La doppia fonte NTC/Eurocodici genera ambiguita' pratiche (quale combinazione, quale coefficiente: la risposta corretta e' 'quella del quadro richiamato dalla legge italiana per quell'opera'); gli NA non sono armonizzati tra paesi: un progetto 'a Eurocodici' per la Francia non e' lo stesso per l'Italia; la mole documentale e' enorme (migliaia di pagine); la seconda generazione introduce transizioni da gestire con attenzione alle date.",
 costi_e_economia="Ordini di grandezza indicativi: la raccolta completa degli Eurocodici con Annessi Nazionali costa centinaia di euro in edizioni o abbonamenti; software di calcolo con moduli Eurocodici+NTC: 1-6 k€/postazione/anno; la formazione specialistica (corsi su singoli volumi) 300-1.500 € a corso; l'errore di coefficiente nazionale scoperto in collaudo costa revisioni e responsabilita': assai di piu'.",
 casi_real_world="Caso tipo: progetto di capannone in acciaio per committente estero: capitolato che richiedeva EN 1993 con Annesso Nazionale del paese di destinazione; il progettista italiano ha verificato i carichi con EN 1991 e NA locale e ha consegnato relazione in doppia lingua con tabella dei NDP utilizzati: approvazione senza integrazioni.",
 normative="Serie EN 1990-1999 (Eurocodici strutturali) con Annessi Nazionali italiani; D.M. 17/1/2018 (NTC: quadro nazionale e rapporto con gli Eurocodici); la seconda generazione degli Eurocodici e' in pubblicazione progressiva (verificare stato e adozioni sulle fonti ufficiali CEN/UNI).",
 note_cantiere="Nella relazione di calcolo apri sempre con la tabella delle fonti: norma, edizione, Annesso Nazionale, valori NDP scelti. E' la pagina che il collaudatore legge per prima e quella che ti salva in revisione: chi trova i coefficienti senza chiederli ti considera serio prima ancora di controllare i conti."
)

add(
 categoria="Eurocodici",
 nome="NTC 2018 ed Eurocodici: il doppio binario italiano e come lavorarci senza incidenti",
 descrizione="In Italia la legge delle costruzioni sono le NTC (D.M. 17/1/2018); gli Eurocodici sono il grande riferimento tecnico europeo richiamato come strumento. Il progettista lavora sul doppio binario: quadro nazionale per obblighi, coefficienti e verifiche; Eurocodici per metodi, dettagli e copertura dei casi non normati. Gli errori nascono dove i due binari si incrociano male.",
 tecnologia="Architettura pratica: le NTC fissano azioni (neve, vento, sisma con parametri nazionali), criteri di sicurezza, combinazioni, verifiche e adempimenti (relazioni, depositi, collaudi); gli Eurocodici con Annesso Nazionale forniscono i metodi di calcolo di dettaglio per materiali e tipologie; le parti degli Eurocodici NON coperte da NA o non richiamate restano riferimento tecnico volontario (regola dell'arte); punti di attrito tipici: coefficienti parziali (NTC vs NA Eurocodici: usare quelli del quadro di riferimento dichiarato, mai miscelare), combinazioni per opere speciali (ponti, serbatoi: verificare il rinvio specifico delle NTC), opere esistenti (quadro NTC dedicato, con livelli di conoscenza: gli Eurocodici non trattano l'esistente), geotecnica (EN 1997 con NA: attenzione agli approcci di progetto dichiarati); documentazione: la relazione deve dichiarare il quadro normativo adottato per intero; nei depositi e collaudi conta la coerenza dichiarata; per l'estero: progetto italiano da usare all'estero va ricalibrato sul quadro di destinazione (e viceversa).",
 applicazioni="Ogni progetto strutturale italiano; gare con capitolati che richiamano Eurocodici; revisioni e collaudi; progettazione per l'estero e verifica di progetti esteri; formazione continua dei progettisti.",
 vantaggi="Il doppio binario da' metodi europei completi dentro un quadro nazionale chiaro su obblighi e adempimenti; le NTC coprono l'esistente e il sisma nazionale meglio di qualunque norma generale; la dichiarazione del quadro nel progetto elimina le ambiguita'.",
 limiti="La miscelazione indebita dei coefficienti e' l'errore piu' diffuso (e piu' pericoloso); le transizioni (revisioni NTC, seconda generazione Eurocodici) creano finestre di incertezza: documentare la data delle fonti; la tentazione del software 'che decide lui' e' forte: il programma applica il set che gli hai detto tu — se sbagli set, sbaglia tutto con grande efficienza.",
 costi_e_economia="Ordini di grandezza indicativi: aggiornamento professionale continuo (corsi, testi) 500-2.000 €/anno per progettista strutturale; software bilingue NTC/Eurocodici 1-6 k€/anno; una revisione di calcolo per quadro normativo errato su opera media: settimane di lavoro e 10-50 k€ tra progettazione e ritardi.",
 casi_real_world="Caso tipo: verifica di un serbatoio in cls: il progetto originale miscelava combinazioni NTC con coefficienti da EN 1992 senza NA; la revisione ha rifatto le verifiche con quadro dichiarato (NTC + EN 1992 con NA dove richiamato) e ha documentato la tabella delle fonti: collaudo superato alla prima presentazione.",
 normative="D.M. 17/1/2018 (NTC) e sua Circolare applicativa; serie EN 1990-1999 con Annessi Nazionali italiani; per le opere speciali i rinvii specifici delle NTC; stato della seconda generazione degli Eurocodici da verificare su fonti CEN/UNI.",
 note_cantiere="Quando prendi in mano un calcolo altrui, la prima domanda non e' 'quanto porta' ma 'con che quadro': se la relazione non dichiara norme, edizioni, NA e set di coefficienti, non fidarti dei numeri che seguono. E nel tuo progetto scrivilo tu per primo: un paragrafo, prima pagina, mai dimenticato."
)

add(
 categoria="Direttive",
 nome="Le direttive UE che stanno ridisegnando l'edilizia: EPBD 'Case Green', RED III, Ecodesign",
 descrizione="Tre direttive/regolamenti europei stanno cambiando il perimetro del lavoro edile: la EPBD 'Case Green' (prestazione energetica degli edifici), la RED III (rinnovabili) e il regolamento Ecodesign per i prodotti sostenibili. Sono il quadro entro cui nascono decreti nazionali, incentivi e obblighi: chi progetta oggi dentro queste direttrici progetta per il mercato di domani.",
 tecnologia="EPBD (Direttiva UE 2024/1275, 'Case Green'): traiettoria verso edifici a emissioni zero, standard minimi di prestazione energetica per il patrimonio esistente, ristrutturazioni profonde, sistemi tecnici per l'edilizia, infrastrutture per la mobilita' elettrica, passaporto di ristrutturazione; richiede recepimento nazionale con scadenze fissate dalla direttiva (l'Italia ha ricevuto sollecitazioni sul recepimento: verificare lo stato su fonti istituzionali); RED III (Direttiva UE 2023/2413): target rinnovabili, semplificazioni autorizzative, target settoriali per edilizia e industria; recepita in Italia con il D.Lgs 5/2026 (che aggiorna il D.Lgs 199/2021); Ecodesign: il Reg. UE 2024/1781 (ESPR) estende l'ecodesign a quasi tutti i prodotti con passaporto digitale del prodotto; per l'edilizia si intreccia con la revisione del CPR e con i requisiti ambientali dei prodotti; il filo comune: obblighi di prestazione energetica/ambientale che scendono su edifici, impianti e prodotti, con tempi scaglionati; per il professionista: leggere i recepimenti nazionali (decreti legislativi e ministeriali), non le sole direttive: le regole operative sono nei testi nazionali.",
 applicazioni="Programmazione delle ristrutturazioni energetiche (edifici pubblici e privati); progettazione NZEB; strategia di prodotto dei fabbricanti; consulenza su incentivi e obblighi; gare pubbliche con criteri ambientali minimi.",
 vantaggi="Il quadro europeo da' visibilita' di lungo periodo: gli investimenti in competenze e tecnologie seguono direttrici decennali; gli incentivi nazionali (Conto Termico, detrazioni) si muovono dentro queste cornici: capire la direttiva anticipa le mosse nazionali; i CAM e i criteri di gara gia' incorporano i requisiti ambientali.",
 limiti="Le direttive non sono regole di cantiere: senza recepimento nazionale non si applicano direttamente ai singoli; i tempi di recepimento italiani slittano (con richiami UE documentati); il rischio e' progettare su annunci: distinguere sempre tra vigente, recepito e annunciato; la stratificazione EPBD+RED+ESPR+CPR genera sovrapposizioni che solo i decreti attuativi risolvono.",
 costi_e_economia="Ordini di grandezza indicativi: la consulenza strategica su adeguamento EPBD/ESPR per un fabbricante o una grande committenza 5-30 k€; per il singolo progetto, la verifica di coerenza con i recepimenti vigenti e' parte della normale progettazione; il ritardo di recepimento ha costi di sistema (incertezza) non imputabili al singolo cantiere.",
 casi_real_world="Caso tipo: amministrazione comunale che programma il piano quinquennale degli edifici scolastici: la progettazione e' stata impostata sugli standard EPBD recepiti e sulle traiettorie nazionali note, con verifica annuale delle scadenze di recepimento: i primi due interventi hanno superato le verifiche di finanziabilita' ministeriale senza integrazioni.",
 normative="Direttiva UE 2024/1275 (EPBD 'Case Green'); Direttiva UE 2023/2413 (RED III) e D.Lgs 5/2026 di recepimento italiano; Reg. UE 2024/1781 (ESPR, Ecodesign per prodotti sostenibili); stato del recepimento nazionale della EPBD da verificare su mase.gov.it e fonti istituzionali; Reg. UE 305/2011 e sua revisione per l'intreccio prodotti.",
 note_cantiere="Costruisci una tabella personale: direttiva | decreto nazionale di recepimento | stato | cosa cambia per i tuoi lavori. Aggiornala due volte l'anno. In riunione coi clienti distingui sempre 'vigente', 'recepito', 'annunciato': la credibilita' professionale si gioca su queste tre parole, non sulle slide."
)

add(
 categoria="Internazionale",
 nome="IBC, IRC, ASCE 7 e NFPA: i codici americani e il confronto col sistema europeo",
 descrizione="Chi lavora con committenti internazionali incontra il sistema americano: International Building Code (IBC) per l'edilizia, IRC per il residenziale, ASCE 7 per i carichi, NFPA per l'antincendio, ACI/AISC per i materiali. Filosofia diversa dalla nostra: codice 'adottato' dalle giurisdizioni locali, forte componente prescrittiva, verifiche LRFD. Conoscerne la logica evita errori di traduzione concettuale.",
 tecnologia="Struttura: i 'model codes' (IBC dell'ICC, NFPA 101/5000, Uniform Plumbing/Mechanical Code) vengono adottati con emendamenti dagli Stati e dalle contee: la legge edilizia e' LOCALE; ASCE 7 fissa carichi minimi (neve, vento, sisma con mappe nazionali); il dimensionamento usa LRFD (Load and Resistance Factor Design): filosofia a coefficienti parziali affine agli stati limite europei ma con valori e combinazioni propri; ACI 318 (cls), AISC 360 (acciaio), NDS (legno), TMS (muratura) coprono i materiali; l'antincendio e' centrato su occupazione, mezzi di fuga e sprinkler (NFPA 13): approccio prestazionale crescente ma base prescrittiva forte; il collaudo passa da Authority Having Jurisdiction (AHJ) e special inspectors; differenze pratiche col sistema italiano: qui legge nazionale tecnica (NTC) + norme volontarie; la' codice adottato localmente + standard richiamati; qui collaudo statico formalizzato; la' ispezioni e special inspection continue; unita' di misura imperiali, terminologia diversa (allowable stress vs strength design), documentazione con 'submittals' approvati prima della posa.",
 applicazioni="Progetti con committenti o sedi USA; confronti prestazionali per gare internazionali; lettura di specifiche americane; cooperazione con studi esteri; valutazione di prodotti certificati per il mercato USA (ICC-ES Evaluation Reports).",
 vantaggi="La logica a codice adottato + ispezioni continue produce controllo di cantiere serrato; gli standard di prova e listing (UL, FM, ICC-ES) danno tracciabilita' dei prodotti; per l'antincendio, l'integrazione sprinkler+compartimentazione e' matura e collaudata; conoscere il LRFD facilita il dialogo tecnico transatlantico.",
 limiti="Non esiste 'il' codice americano: esiste quello adottato da quella giurisdizione in quell'anno (verificare SEMPRE l'adozione locale); la traduzione automatica dei coefficienti tra sistemi e' un errore tecnico grave; la base prescrittiva puo' imporre soluzioni diverse da quelle ottimali in logica europea; il sistema di responsabilita' e assicurazione professionale e' diverso: i contratti vanno letti con consulenti locali.",
 costi_e_economia="Ordini di grandezza indicativi: accesso ai codici (ICC, NFPA, ASCE) in abbonamento 500-2.000 €/anno; consulenza di code compliance locale su progetto medio 5-20 k€; la verifica di un prodotto per listing ICC-ES da parte del fabbricante 20-100 k€; errori di 'traduzione' tra sistemi in gara: revisioni e contenziosi ben oltre i 10 k€.",
 casi_real_world="Caso tipo: impresa italiana impegnata su struttura per impianto industriale negli USA: il capitolato richiedeva ASCE 7 per i carichi e AISC 360 per le membrature; la verifica e' stata eseguita con software impostato sul set USA (combinazioni LRFD) e la relazione approvata dall'ingegnere strutturista locale registrato, con submittals delle connessioni prima della produzione.",
 normative="International Building Code (IBC) e International Residential Code (IRC) dell'ICC; ASCE/SEI 7 (carichi minimi); ACI 318 (cls), AISC 360 (acciaio), NDS (legno); NFPA 101 e NFPA 5000 (sicurezza e codice edilizio antincendio), NFPA 13 (sprinkler); ICC-ES per i rapporti di valutazione dei prodotti; l'adozione avviene a livello di Stato/contea: verificare sempre la giurisdizione specifica.",
 note_cantiere="Lavorando per gli USA: prima cosa chiedi 'quale edizione del codice ha adottato questa contea?' e 'chi e' l'AHJ?'. Seconda: niente conversioni a memoria tra sistemi — i coefficienti LRFD non sono i nostri stati limite con un altro nome. Terza: i submittals si approvano PRIMA di produrre: chi produce prima e sottomette dopo, smonta e paga."
)

add(
 categoria="Internazionale",
 nome="ISO, EN, UNI: leggere la sigla di una norma come una carta d'identita'",
 descrizione="UNI EN ISO 9001, EN 1997-1, UNI/TR, prEN: la sigla di una norma racconta chi l'ha scritta, a che livello vale e in che stato si trova. Saperla leggere evita di citare progetti come norme, guide come requisiti, edizioni nazionali come europee. E' l'alfabeto minimo del professionista tecnico.",
 tecnologia="Enti e livelli: ISO (mondiale), CEN/CENELEC (europei: EN), UNI (italiano); prefissi composti: UNI EN = norma europea adottata identica in italiano; UNI EN ISO = norma ISO adottata a livello europeo e poi nazionale; EN ISO = ISO adottata in Europa; documenti non-norma: UNI/TS (specifica tecnica: pre-standard, vita breve), UNI/TR (rapporto tecnico: informativo, nessun requisito), guide CEN; stati di vita: prEN (progetto europeo in inchiesta: NON citabile come requisito), EN pubblicata, edizioni nazionali con prefacce e annessi informativi; ritiro e sostituzione ('sostituita da'); la numerazione: famiglia.numero-parte:anno (UNI EN 1997-1:2013); le norme armonizzate CPR sono EN citate in GUUE (vedi scheda dedicata); i corrigendum (AC) modificano il testo: citare l'edizione CON i corrigendum; per i prodotti: la marcatura CE si fonda sulla EN armonizzata citata, non su 'una norma simile'; per il lavoro: la data dell'edizione nel riferimento documentale e la verifica dello stato sul catalogo dell'ente sono passaggi obbligati.",
 applicazioni="Citazioni corrette in capitolati, relazioni e contratti; lettura delle DoP e delle ETA; gestione documentale di studio; formazione e aggiornamento; contenziosi (la citazione sbagliata si ribalta).",
 vantaggi="La sigla letta bene dice subito: vincolante o volontaria, vigente o morta, requisito o informazione; evita figuracce nei documenti ufficiali; velocizza la ricerca del documento giusto; in gara internazionale mostra padronanza del sistema.",
 limiti="Le banche dati degli enti non sempre mostrano gratuitamente lo stato completo; i corrigendum si perdono facilmente (la stampa 'base' resta in circolo); le traduzioni nazionali possono contenere note che non sono nel testo europeo (e viceversa); il progetto prEN circola in bozze riservate: citarlo e' un autogol.",
 costi_e_economia="Ordini di grandezza indicativi: singola norma 40-120 €; abbonamento al catalogo con alert 300-1.500 €/anno; un fascicolo normativo ordinato per studio: giorni di lavoro una tantum; il riferimento errato in un atto di gara o in una perizia: costi legali e di credibilita' di ordine ben superiore.",
 casi_real_world="Caso tipo: perizia che citava una UNI/TR come 'norma di riferimento per l'accettazione': la controparte ha fatto notare che un rapporto tecnico non contiene requisiti; la CTU ha ridimensionato quel capitolo della perizia. Lezione documentata: prima di citare, leggere il frontespizio.",
 normative="Reg. UE 1025/2012 (quadro della standardizzazione europea); regole di adozione CEN/UNI (prefazioni delle singole norme); cataloghi pubblici UNI, CEN, ISO per stati ed edizioni; Reg. UE 305/2011 per il raccordo con le norme armonizzate.",
 note_cantiere="Quando copi una citazione da un vecchio capitolato, spendi un minuto sul catalogo UNI: edizione, stato, corrigendum. Le citazioni ereditate sono come gli scavi ereditati: nessuno sa cosa c'e' sotto finche' non guarda. E nei tuoi documenti scrivi sempre l'anno dell'edizione: 'UNI EN 1997-1' senza anno e' una citazione a meta'."
)

add(
 categoria="Pratica",
 nome="Verificare certificati e marchi: falsi documenti, banche dati e controlli in due minuti",
 descrizione="Il mercato dei materiali vive di documenti: DoP, certificati di costanza, marchi volontari, rapporti di prova. Quasi tutti verificabili online in pochi minuti — e quasi mai verificati. I falsi esistono: marchi CE apposti fuori dal CPR, certificati scaduti, organismi inesistenti. Il controllo documentale e' il controllo qualita' piu' economico del cantiere.",
 tecnologia="Catena documentale del prodotto: DoP (fabbricante) -> certificato di costanza della prestazione (organismo notificato, se AVCP lo richiede) -> rapporti di prova (laboratorio) -> marchi volontari (ente terzo: qualita' oltre il minimo); verifiche operative: (1) numero organismo notificato sulla marcatura CE: controllo sulla banca dati NANDO (nome, campo di notifica, stato); (2) ETA: verifica presso il TAB emittente o EOTA (versione e validita'); (3) laboratori di prova: accreditamento ISO/IEC 17025 verificabile presso l'ente nazionale di accreditamento (in Italia Accredia); (4) marchi volontari: regolamento del marchio e elenco licenziatari sul sito dell'ente; (5) coerenza interna: norma citata vs prodotto, edizione vs stato di pubblicazione, campo d'impiego vs uso previsto in cantiere; segnali d'allarme: DoP senza norma armonizzata dove serve, 'CE' su prodotti fuori CPR, certificati senza numero o con ente ignoto, prezzi anomali, documenti fotocopiati senza riferimenti; in appalto pubblico: i controlli documentali sono parte dell'accettazione in corso d'opera.",
 applicazioni="Accettazione materiali in cantiere; qualifica dei fornitori; gare pubbliche e private; perizie e contenziosi; audit di sorveglianza; importazione diretta di prodotti extra-UE (il rischio documentale sale).",
 vantaggi="Costo quasi nullo a fronte di rischio enorme; la verifica crea responsabilita' a catena (il fornitore verificato documenta meglio); il fascicolo verificato vale in garanzia e in giudizio; le banche dati ufficiali sono pubbliche e gratuite.",
 limiti="Le banche dati non sono perfettamente sincronizzate (un organismo legittimo appena notificato puo' mancare temporaneamente); la verifica documentale non sostituisce le prove in sito dove servono (campioni, lotti); i documenti veri su prodotto non conforme esistono (il documento e' genuino, il lotto no): il controllo documentale e' necessario, non sufficiente; richiede disciplina: va fatto su OGNI consegna rilevante, non a campione quando capita.",
 costi_e_economia="Ordini di grandezza indicativi: verifica documentale di una consegna: 10-30 minuti; audit documentale completo di una commessa media: 1-3 giornate (1-3 k€ di DL/consulente); il costo del mancato controllo: sostituzione di partite, fermi cantiere, responsabilita' — da 10 k€ in su anche su opere modeste.",
 casi_real_world="Caso tipo: fornitura di porte tagliafuoco con marcatura CE e certificato di costanza: la verifica NANDO ha mostrato l'organismo non notificato per quella famiglia di prodotti; richiesta documentazione al fornitore, che ha ammesso certificazione in corso: fornitura respinta e sostituita con prodotto pienamente certificato, senza fermi grazie alla verifica pre-consegna.",
 normative="Reg. UE 305/2011 (sistema di dichiarazione e verifica); D.Lgs 106/2017 (sorveglianza del mercato in Italia); ISO/IEC 17025 (accreditamento laboratori); banche dati ufficiali: NANDO (organismi notificati), EOTA/TAB (ETA), Accredia (laboratori accreditati); regolamenti dei singoli marchi volontari.",
 note_cantiere="Istituisci il 'verbale di verifica documentale' per le consegne rilevanti: prodotto, lotto, DoP ricevuta, organismo verificato su NANDO, esito. Ci vogliono dieci minuti a consegna. Il giorno che trovi il documento falso — e prima o poi lo trovi — quel verbale ti copre e blocca il problema al camion, non dentro l'opera."
)

add(
 categoria="Pratica",
 nome="La norma nel contratto e in cantiere: capitolati, accettazione e responsabilita'",
 descrizione="La norma tecnica diventa obbligo quando il contratto la richiama: capitolato, computo, piano di posa. Scrivere bene i richiami normativi (norma giusta, edizione giusta, prestazione verificabile) e' la differenza tra un contratto che protegge e uno che genera dispute. In cantiere, l'accettazione per controlli documentali e prove traduce la norma in esecuzione.",
 tecnologia="Regola dei richiami: citare norma con edizione (anno) o prevedere espressamente 'edizione vigente alla data di...'; distinguere requisiti (si verificano) da riferimenti generici; trasformare le prestazioni normative in controlli: per ogni richiamo, chiedersi 'chi controlla cosa, quando, con quale esito scritto' (controlli di accettazione in fornitura, prove in corso d'opera, collaudi); catena delle responsabilita': il progettista specifica, il DL verifica, l'impresa esegue e documenta, il fornitore dichiara (DoP), il laboratorio prova (accreditato); errori tipici: richiamo a norme ritirate, richiami cumulativi contraddittori (due norme che si sovrappongono con requisiti diversi), criteri di accettazione assenti ('conforme alla norma' senza dire come si dimostra), classi o valori non compatibili col contesto (classe sbagliata per l'uso); nei capitolati pubblici: i richiami normativi interagiscono con il D.Lgs 36/2023 e con i CAM; la documentazione di accettazione alimenta il fascicolo dell'opera e la garanzia decennale (art. 1669 c.c.: la conformita' documentata e' la difesa).",
 applicazioni="Redazione di capitolati e computi; piani di controllo qualita' di cantiere; accettazione forniture e lavorazioni; gestione delle non conformita'; contenziosi e garanzie; gare pubbliche con verifiche di offerta tecniche.",
 vantaggi="Il richiamo preciso rende l'offerta confrontabile e l'esecuzione verificabile; i criteri di accettazione scritti eliminano le dispute 'a sensazione'; la catena documentale continua protegge tutti gli anelli onesti (progettista, DL, impresa); la garanzia decennale si gestisce con la documentazione, non con la memoria.",
 limiti="Scrivere bene i richiami costa tempo in fase di progetto (si risparmia male); il proliferare di richiami non coordinati tra capitolato, computo e disegni genera contraddizioni interne; il controllo documentale richiede personale che sa leggere le norme (competenza da mantenere); le edizioni cambiano a commessa avviata: serve la clausola di gestione delle sostituzioni.",
 costi_e_economia="Ordini di grandezza indicativi: revisione specialistica dei richiami normativi di un capitolato medio: 1-5 k€ (giornate di tecnico); piano di controllo qualita' con prove e accettazioni: 0,5-1,5% del costo dei lavori; la lite su conformita' non documentata: perizie e legali da 10 k€ in su, con esiti incerti per entrambe le parti.",
 casi_real_world="Caso tipo: appalto di impermeabilizzazioni con capitolato che fissava per ogni lavorazione: norma di prodotto ed edizione, classe richiesta, documento di accettazione (DoP + lotto), prova in corso d'opera (spessori, giunti), verbale finale; a fine lavori il fascicolo completo ha permesso l'attivazione immediata della garanzia e zero contestazioni in contabilita' finale.",
 normative="Reg. UE 305/2011 (DoP e responsabilita'); D.Lgs 36/2023 (appalti: documentazione e verifiche); art. 1669 c.c. (garanzia per rovina e difetti); D.M. 17/1/2018 e quadro NTC per le opere strutturali; le singole norme tecniche richiamate nei capitolati con le loro edizioni vigenti; D.Lgs 106/2017 per la sorveglianza dei prodotti.",
 note_cantiere="Prima di firmare il capitolato, fai il 'giro dei controlli': per ogni requisito chiedi ad alta voce 'come lo dimostriamo in cantiere?'. Se la risposta e' un silenzio imbarazzato, il requisito e' decorativo: o gli dai un controllo (documento, misura, prova) o lo levi. Un capitolato con dieci requisiti verificabili batte uno con cento requisiti poetici."
)

